+                    ok = false;
+                    break;
+                }
+            } else if (op == 2) {
+                if (mine.contains(key) != ref.contains(key)) {
+                    ok = false;
+                    break;
+                }
+            } else if (mine.size() != ref.size()) {
+                ok = false;
+                break;
+            }
+        }
